// partition around random pivot, keep only the side containing index k
while(l < r){
  swap(a[l + rng() % (r - l + 1)], a[r]);
  int pv = a[r], i = l;
  for(int j = l; j < r; j++) if(a[j] < pv) swap(a[i++], a[j]);
  swap(a[i], a[r]);
  if(i == k) return a[i];
  if(i < k) l = i + 1; else r = i - 1;
}

